// TH15 v1.00b st04.ecl MainSub03 (源 1154-1187); 敌 ECir03 (291-315) + ECir03_at1 (317-348).
// 源 t0 = MainSub03 入口；卡帧0 = phase 开段，源 wait(120) 保留在 wave 内。
// 章节入口/刷怪门控已删；N/H/L 击破额外发弹（setDeath ECir02DeadAttack1/Et1）按任务选择省略。
const TIME_LIMIT: int = 1524;
const TH15_BIG_BALL: int = 640;

// 源 ECir03_at1：etSprite(18,3)/etAim(1)/etCount(3,1)/etSpeed(3.0,0.2)，
// 每 60 帧一发 3 路扇形，20 发；中心角 = ANGLE_PLAYER + RANDF2*(2deg)。
// 扇形相邻角：E 为 10deg，N/H/L 为 45deg（源 !E / !N / !H / !LO 裸值栈参数）。
async sub at1_fire() {
    var step: angle = 45deg;
    if global(GVAR_RANK) == 0 { step = 10deg; }
    sh_reset(0);
    sh_sprite(0, TH15_BIG_BALL, 3);
    sh_aim(0, 0);
    sh_ring(0, 0);
    sh_count(0, 3, 1);
    sh_speed(0, 3fx, 0fx);
    wait(rand(40)); // 源 wait($RAND % 40)
    for k in 0..20 {
        // 源每次 etAngle 读一次 RANDF2；0.034906585rad = 2deg = 364 BAM。
        var u: fx = (rand(65536)-32768) as fx / 32768;
        var off: int = (364fx*u) as int;
        sh_angle(0, aim_player()+(off as angle), step);
        sh_fire(0);
        wait(60);
    }
}

// 源 ECir03 存活路径。dir = %F0，quarter 为源 moveAngleTime(60,7,%F1) 每 30 帧的累计角；
// 源每帧 += 3deg，共 180deg，拆两段 90deg 以避免目标最短弧在恰好 180deg 上取反。
async sub ecir(dir: angle, quarter: angle) {
    set_invuln(65535);
    set_hitbox(8fx);  // 源 setHitbox(16,16)，普通圆半径取第一值*0.5
    set_hurtbox(12fx); // 源 setHurtbox(24,24)
    spawn at1_fire(); // 源 @ECir03_at1() async；新任务次帧首跑
    move_vel(0, dir, 5fx, EASE_LINEAR); // 源 moveVel(%F0, 5.0)
    wait(50); // 源 wait($I0)，$I0=50
    move_angle(30, dir+quarter, EASE_LINEAR);
    wait(30);
    move_angle(30, dir+quarter+quarter, EASE_LINEAR);
    wait(30);
    wait(60); // 源 moveAngleTime 结束后 wait(60)
    loop { wait(1000); } // 源 ECir03_416/436 循环
}

async sub wave() {
    wait(120); // 源入口 wait(120)
    for i in 0..10 {
        _ = spawn_enemy(-224fx, 64fx, 100, 0, 0, 0, ecir(0bam, 16384bam));
        _ = spawn_enemy(224fx, 64fx, 100, 0, 0, 0, ecir(32768bam, -16384bam));
        wait(10);
    }
    wait(180);
    for j in 0..10 {
        _ = spawn_enemy(-192fx, -32fx, 100, 0, 0, 0, ecir(14336bam, -16384bam));
        _ = spawn_enemy(192fx, -32fx, 100, 0, 0, 0, ecir(18432bam, 16384bam));
        wait(10);
    }
    wait(180); // 源 1187
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
